function drawTree(t){const p=project(t.x,t.z);if(!p||p.scale<.018)return;let r=t.r*p.scale,h=t.h*p.scale;if(p.y<H*.48)return;const ground=p.y;ctx.fillStyle='#454a3c';ctx.fillRect(p.x-r*.16,ground-h*.3,r*.32,h*.3);ctx.fillStyle=t.tone?'#515d48':'#465746';ctx.beginPath();ctx.moveTo(p.x,ground-h);ctx.lineTo(p.x-r*.88,ground-h*.28);ctx.lineTo(p.x-r*.5,ground-h*.34);ctx.lineTo(p.x-r,ground);ctx.lineTo(p.x+r,ground);ctx.lineTo(p.x+r*.48,ground-h*.4);ctx.lineTo(p.x+r*.85,ground-h*.35);ctx.closePath();ctx.fill();ctx.fillStyle='#82906b4a';ctx.beginPath();ctx.ellipse(p.x-r*.2,ground-h*.67,r*.25,h*.13,-.3,0,TAU);ctx.fill()}
