ctx.fillStyle=enemy?'#322f2c':a===player?'#303a32':'#39423b';ctx.fillRect(-sz*.29,-sz*.46,sz*.2,sz*.46);ctx.fillRect(sz*.08,-sz*.46,sz*.2,sz*.46);ctx.fillStyle=enemy?'#62443d':a===player?'#596b4d':'#4a605d';ctx.beginPath();ctx.moveTo(-sz*.38,-sz*.43);ctx.lineTo(-sz*.32,-sz*.99);ctx.lineTo(0,-sz*1.08);ctx.lineTo(sz*.32,-sz*.99);ctx.lineTo(sz*.38,-sz*.43);ctx.closePath();ctx.fill();ctx.fillStyle=enemy?'#c58f75':'#d6b49a';ctx.beginPath();ctx.ellipse(0,-sz*1.22,sz*.2,sz*.23,0,0,TAU);ctx.fill();ctx.fillStyle=enemy?'#271f1e':'#292e29';ctx.beginPath();ctx.ellipse(0,-sz*1.32,sz*.22,sz*.12,0,Math.PI,TAU);ctx.fill();ctx.fillStyle=enemy?'#ff9b72':'#e4f29d';ctx.fillRect(-sz*.12,-sz*1.24,sz*.06,sz*.025);ctx.fillRect(sz*.06,-sz*1.24,sz*.06,sz*.025);ctx.fillStyle='#333834';ctx.fillRect(sz*.22,-sz*.84,sz*.55,sz*.08);ctx.fillStyle='#9da28d';ctx.fillRect(sz*.62,-sz*.87,sz*.12,sz*.04);ctx.shadowBlur=0;
