function drawAtmosphere(dt){if(world.weather>0){ctx.fillStyle=`rgba(199,180,136,${world.weather*.025})`;ctx.fillRect(0,0,W,H);for(let i=0;i<30;i++){const x=(i*197+now*.026)%W,y=(i*113+now*.045)%H;ctx.fillStyle='#e7d5ac39';ctx.fillRect(x,y,1,2)}}}
function render(t){requestAnimationFrame(render);if(paused)return;const dt=Math.min(.04,(t-last)/1000||.016);last=t;now=t;update(dt);ctx.setTransform(DPR,0,0,DPR,0,0);ctx.clearRect(0,0,W,H);ctx.save();if(shake>0){ctx.translate(rand(-shake,shake),rand(-shake,shake));shake=Math.max(0,shake-dt*20)}drawSky();drawZone();const objects=[...buildings.map(o=>({type:'b',o,depth:dist(player,o)})),...trees.map(o=>({type:'t',o,depth:dist(player,o)})),...debris.map(o=>({type:'d',o,depth:dist(player,o)})),...loot.filter(l=>!l.taken).map(o=>({type:'l',o,depth:dist(player,o)})),...squad.slice(1).map(o=>({type:'a',o,depth:dist(player,o)})),...enemies.filter(e=>e.alive).map(o=>({type:'e',o,depth:dist(player,o)}))].sort((a,b)=>b.depth-a.depth);for(const ob of objects){if(ob.depth>950)continue;if(ob.type==='b')drawBuilding(ob.o);else if(ob.type==='t')drawTree(ob.o);else if(ob.type==='d')drawDebris(ob.o);else if(ob.type==='l')drawLoot(ob.o);else if(ob.type==='a')drawAgent(ob.o);else drawAgent(ob.o,true)}for(const tr of tracers)drawTracer(tr);drawWeapon();drawAtmosphere(dt);ctx.restore();}
