function say(text){const t=$('#toast');t.textContent=text;t.classList.add('visible');clearTimeout(say.timer);say.timer=setTimeout(()=>t.classList.remove('visible'),1900)}
function update(dt){if(ended)return;world.day=(.76+Math.sin(now*.000035)*.12);world.weather=.5+.5*Math.sin(now*.00019);player.shot=Math.max(0,player.shot-dt*4);player.spread=Math.max(0,player.spread-dt*.42);player.scan=Math.max(0,player.scan-dt);player.dash=Math.max(0,player.dash-dt);player.reload=Math.max(0,player.reload-dt);if(player.reload===0&&player.reloading){const n=Math.min(30-player.ammo,player.reserve);player.ammo+=n;player.reserve-=n;player.reloading=false;updateHud()}
