set -euo pipefail
/usr/bin/chromium

input.command:
node <<'NODE'
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox']});
 const page=await browser.newPage({viewport:{width:1280,height:720},deviceScaleFactor:1});
 const errors=[];page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
 await page.goto('http://127.0.0.1:3000',{waitUntil:'networkidle'});
 await page.waitForTimeout(1200);
 const init={title:await page.title(),canvas:await page.locator('#world').evaluate(c=>[c.width,c.height]),ammo:await page.locator('#ammoClip').innerText(),hp:await page.locator('#hpText').innerText(),errors};
 await page.keyboard.down('w');await page.waitForTimeout(500);await page.keyboard.up('w');
 await page.keyboard.press('q');await page.keyboard.press('f');await page.keyboard.press('g');await page.waitForTimeout(150);
 const after={toast:await page.locator('#toast').innerText(),scan:await page.locator('#scanFlash').getAttribute('class'),errors};
 await page.keyboard.press('Escape');const paused=await page.locator('#modalTitle').innerText();await page.locator('#resumeBtn').click();
 await page.screenshot({path:'/tmp/opencode/last-light-check.jpg',type:'jpeg',quality:80});
 console.log(JSON.stringify({init,after,paused,resumed:await page.locator('#modal').getAttribute('class'),screenshot:'/tmp/opencode/last-light-check.jpg'},null,2));
 await browser.close();
})();
